function loadDisciplineProfile(PDO $pdo,int $id,string $dance,array $legacy):array{$s=$pdo->prepare('SELECT dance_role,current_division FROM bdc_competitor_discipline_profiles WHERE competitor_id=:id AND dance_style=:dance LIMIT 1');$s->execute(['id'=>$id,'dance'=>$dance]);$p=$s->fetch()?:($dance==='bachata'?['dance_role'=>$legacy['dance_role']??'unknown','current_division'=>$legacy['current_division']??'unknown']:['dance_role'=>'unknown','current_division'=>'unknown']);$categories=$pdo->prepare('SELECT category FROM bdc_competitor_special_categories WHERE competitor_id=:id AND dance_style=:dance ORDER BY category');$categories->execute(['id'=>$id,'dance'=>$dance]);$p['special_categories']=$categories->fetchAll(PDO::FETCH_COLUMN);return$p;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Csrf::verify($_POST['_csrf']??null))$error='Invalid security token.';
 else{
