ype="checkbox" name="show_on_leaderboard" id="show" <?=$c['show_on_leaderboard']?'checked':''?>><label class="form-check-label" for="show">Show on public leaderboard</label></div></div><?php if($dance==='bachata'):?><div class="col-12"><div class="card border-warning-subtle bg-warning-subtle"><div class="card-body"><h2 class="h6 mb-3">Manual division eligibility · Bachata</h2><p class="small text-muted">These legacy overrides apply to Bachata only.</p><div class="row g-3"><div class="col-md-4"><div class="form-check"><input class="form-check-input" type="checkbox" name="novice_manual_out" id="noviceManualOut" <?=!empty($c['novice_manual_out'])?'checked':''?>><label class="form-check-label fw-semibold" for="noviceManualOut">Manually mark out of Novice</label></div></div><div class="col-md-4"><div class="form-check"><input class="form-check-input" type="checkbox" name="intermediate_manual_out" id="intermediateManualOut" <?=!empty($c['intermediate_manual_out'])?'checked':''?>><label class="form-check-label fw-semibold" for="intermediateManualOut">Manually mark out of Intermediate</label></div></div><div class="col-md-4"><label class="form-label">Reason</label><input class="form-control" name="division_override_reason" value="<?=e((string)$c['division_override_reason'])?>"></div></div></div></div></div><?php endif;?><div class="col-12"><label class="form-label">Internal admin notes</label><textarea class="form-control" rows="3" name="admin_notes"><?=e((string)$c['admin_notes'])?></textarea></div></div></div></div></div><div class="card-footer bg-white p-3 d-flex gap-2"><button class="btn btn-dark">Save <?=e(ucfirst($dance))?> profile</button><a class="btn btn-outline-secondary" href="./">Back</a></div></form>
